const people=['Eduardo','Jéssica'],photos=['edu.webp','jess.webp'],tags=['Teve briga','Dia feliz','Dia quente'],names=['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];
const empty=()=>({tags:[],who:'Os dois',note:'',votes:[null,null]});
const members=['eduardo','jessica'],kinds=['briga','feliz','quente'],ms=86400000;
let days={},events=[],day,todayKey,draft,person,rating,revision,saving=false,dragging=false,dragMoved=false,dragStart=0,scrollStart=0;
const el=id=>document.getElementById(id),modal=el('modal'),form=el('form');
const localDate=new Date(); localDate.setHours(0,0,0,0);
const keyFromDate=date=>{const d=new Date(date);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const dateFromKey=key=>new Date(key+'T00:00:00Z');
const keyFromUtcDate=date=>{const d=new Date(date);return d.getUTCFullYear()+'-'+String(d.getUTCMonth()+1).padStart(2,'0')+'-'+String(d.getUTCDate()).padStart(2,'0')};
const shiftKey=(key,days)=>keyFromUtcDate(new Date(dateFromKey(key).getTime()+days*ms));
todayKey=keyFromDate(localDate);
const dateLabel=key=>dateFromKey(key).toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'2-digit',timeZone:'UTC'});
const fullDateLabel=key=>dateFromKey(key).toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric',timeZone:'UTC'});
const escapeText=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function initialize(){
 const response=await fetch('/api/dados',{cache:'no-store'});if(!response.ok)throw new Error('Falha ao carregar dados do Supabase');
  const source=response.headers.get('X-Data-Source');setDataStatus(source==='supabase'?'Supabase conectado':source==='github-fallback'?'Supabase fora · fallback ativo':'Supabase não configurado · JSON local');
 const db=await response.json();revision=response.headers.get('ETag');
 for(const [date,rec] of Object.entries(db.registros))days[date]={tags:rec.marcacoes.map(k=>kinds.indexOf(k)),who:rec.envolvidosNaBriga||'Os dois',note:rec.observacao,votes:members.map(id=>rec.votos[id]?{score:rec.votos[id].estrelas,note:rec.votos[id].comentario}:null)};
  try{const eventsResponse=await fetch('/api/eventos',{cache:'no-store'});if(eventsResponse.ok)events=await eventsResponse.json()}catch{}
  render();
}
function setDataStatus(message){const status=el('dataStatus');if(status){status.hidden=false;status.textContent=message;status.dataset.state=message.includes('conectado')?'ok':message.includes('fora')?'warning':'offline'}}
const done=d=>days[d]?.votes.every(Boolean);
const toApiRecord=record=>({marcacoes:record.tags.map(i=>kinds[i]),envolvidosNaBriga:record.tags.includes(0)?record.who:null,observacao:record.note,votos:Object.fromEntries(members.map((id,i)=>[id,record.votes[i]?{estrelas:record.votes[i].score,comentario:record.votes[i].note}:null]))});
async function persist(record){
 if(saving)return;saving=true;const selected=day;const data=toApiRecord(record);
  try{const response=await fetch('/api/dados',{method:'PUT',headers:{'Content-Type':'application/json','If-Match':revision},body:JSON.stringify({data:selected,registro:data})});if(response.status===412){alert('Os dados mudaram. Recarregue a página para conferir a versão mais recente antes de salvar.');return}if(!response.ok)throw new Error();revision=response.headers.get('ETag');days[selected]=record;render();if(modal.open&&day===selected)overview()}catch{alert('Não foi possível salvar no Supabase. Confira a conexão e tente novamente.')}finally{saving=false}
}
function trailDates(){const future=Array.from({length:101},(_,i)=>keyFromDate(new Date(localDate.getTime()+i*ms)));return [...new Set([shiftKey(todayKey,-1),...Object.keys(days),...future])].sort()}
function render(){
 const yesterday=shiftKey(todayKey,-1);let streak=0,current=days[todayKey]?todayKey:yesterday;for(let d=current;days[d]&&!days[d].tags.includes(0);d=shiftKey(d,-1))streak++;
 el('todayLabel').textContent=fullDateLabel(todayKey).toUpperCase();el('trailMonth').textContent=dateFromKey(todayKey).toLocaleDateString('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}).toUpperCase();el('count').textContent=streak;el('streakLabel').textContent=streak===1?'dia sem briga':'dias sem briga';el('week').innerHTML=names.map(n=>'<span><b>·</b>'+n+'</span>').join('');el('go').hidden=Boolean(days[todayKey]);
 const previous=Object.keys(days).filter(d=>d<todayKey).sort().pop(),featuredDay=days[todayKey]?.votes.some(Boolean)?todayKey:previous;renderHighlights(featuredDay);renderHistory();renderRoad();
}
function renderRoad(){const dates=trailDates(),road=el('road'),height=[42,66,30,56,36,62,34],stepWidth=100,points=dates.map((_,i)=>({x:i*stepWidth+stepWidth/2,y:height[i%height.length]}));let path='M'+points[0].x+' '+points[0].y;for(let i=1;i<points.length;i++){const mid=(points[i-1].x+points[i].x)/2;path+=' C'+mid+' '+points[i-1].y+' '+mid+' '+points[i].y+' '+points[i].x+' '+points[i].y}const line='<svg class="trail-line" aria-hidden="true" viewBox="0 0 '+dates.length*stepWidth+' 110" preserveAspectRatio="none"><path d="'+path+'" fill="none" stroke="#dda9c7" stroke-width="2" stroke-dasharray="3 6" stroke-linecap="round" vector-effect="non-scaling-stroke"/></svg>';road.style.width=dates.length*stepWidth+'px';road.innerHTML=line+dates.map((d,i)=>{const date=dateFromKey(d),future=d>todayKey,status=future?'Em breve':done(d)?'Concluído':days[d]?'Em andamento':'Registrar',symbol=future?'·':done(d)?'✓':d===todayKey?'♥':'+';return '<div class="step '+(future?'future ':'')+(d===todayKey?'active ':'')+(days[d]?'recorded':'')+'" data-date="'+d+'" style="left:'+(i*stepWidth+stepWidth/2)+'px;top:'+points[i].y+'px"><button class="node" aria-label="'+dateLabel(d)+', '+status+'" '+(future?'disabled':'')+'>'+symbol+'</button><div class="step-label"><b>'+date.toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',timeZone:'UTC'})+'</b><em>'+(d===todayKey?'Hoje · ':'')+status+'</em></div></div>'}).join('');road.querySelectorAll('.step:not(.future) .node').forEach(button=>button.addEventListener('click',()=>openDay(button.closest('.step').dataset.date)));setTimeout(focusToday,0)}
function focusToday(){const target=document.querySelector('[data-date="'+todayKey+'"]');if(target)target.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})}
function moveCarousel(direction){el('roadScroll').scrollBy({left:direction*230,behavior:'smooth'})}
function setupDrag(){const viewport=el('roadScroll');viewport.addEventListener('pointerdown',event=>{dragging=true;dragMoved=false;dragStart=event.clientX;scrollStart=viewport.scrollLeft;viewport.setPointerCapture(event.pointerId);viewport.classList.add('dragging')});viewport.addEventListener('pointermove',event=>{if(dragging){dragMoved=dragMoved||Math.abs(event.clientX-dragStart)>5;viewport.scrollLeft=scrollStart-(event.clientX-dragStart)}});viewport.addEventListener('click',event=>{if(dragMoved){event.preventDefault();event.stopPropagation();dragMoved=false}},true);viewport.addEventListener('pointerup',stopDrag);viewport.addEventListener('pointercancel',stopDrag);viewport.addEventListener('lostpointercapture',stopDrag)}
function stopDrag(){dragging=false;el('roadScroll').classList.remove('dragging')}
function renderSpecialEvents(date){return events.filter(event=>event.dataInicio<=date&&event.dataFim>=date).map(event=>{const items=event.itens.filter(item=>item.data===date);return '<section class="day-event"><small>EVENTO ESPECIAL</small><b>'+escapeText(event.tipo)+' · '+escapeText(event.participante)+'</b>'+(event.descricao?'<p>'+escapeText(event.descricao)+'</p>':'')+(items.length?items.map(item=>'<p class="day-event-note"><time>'+dateLabel(item.data)+'</time>'+escapeText(item.observacao)+'</p>').join(''):'')+'</section>'}).join('')}
function renderHistory(){const eventDates=events.flatMap(event=>[event.dataInicio,event.dataFim,...event.itens.map(item=>item.data)]),dates=[...new Set([...Object.keys(days),todayKey,shiftKey(todayKey,-1),...eventDates])].sort((a,b)=>b.localeCompare(a));el('entries').innerHTML=dates.map(d=>{const record=days[d],edit='<button class="edit-day" onclick="openDay(\''+d+'\')" aria-label="Editar registro de '+dateLabel(d)+'" title="Editar registro">&#9998;</button>';if(!record)return '<article class="entry empty-entry"><h3><span>'+dateLabel(d)+'</span>'+edit+'</h3><div><p class="muted">Nenhum registro lançado para este dia.</p><button class="sub" onclick="openDay(\''+d+'\')">Registrar este dia</button>'+renderSpecialEvents(d)+'</div></article>';const choices=record.tags.map(i=>tags[i]+(i===0?' ('+escapeText(record.who)+')':'')).join(' · '),voices=people.map((name,i)=>{const vote=record.votes[i],comment=vote?escapeText(vote.note||'Sem comentário.'):'Voto pendente.';return '<p class="voice"><img src="'+photos[i]+'" alt=""><span><strong>'+name+'</strong> '+(vote?'<small>'+vote.score+'/5 ★</small>':'')+'<span class="written">'+comment+'</span></span></p>'}).join(''),pending=!done(d);return '<article class="entry"><h3><span>'+dateLabel(d)+'</span>'+edit+'</h3><div><p class="shared"><b>'+choices+'</b>'+(record.note?' · '+escapeText(record.note):'')+'</p>'+voices+(pending?'<button class="sub history-action" onclick="openDay(\''+d+'\')">Completar votação</button>':'')+renderSpecialEvents(d)+'</div></article>'}).join('')}
function showHistory(panel){const daily=panel==='daily';el('dailyPanel').hidden=!daily;el('eventsPanel').hidden=daily;el('dailyTab').classList.toggle('active',daily);el('eventsTab').classList.toggle('active',!daily);el('dailyTab').setAttribute('aria-selected',daily);el('eventsTab').setAttribute('aria-selected',!daily);if(!daily)renderEvents()}
function eventDateRange(event){return event.dataInicio===event.dataFim?dateLabel(event.dataInicio):dateLabel(event.dataInicio)+' a '+dateLabel(event.dataFim)}
function renderEvents(){el('events').innerHTML=events.map(event=>'<article class="special-event"><div class="event-meta"><small>'+escapeText(event.tipo)+' · '+escapeText(event.participante)+'</small><b>'+eventDateRange(event)+'</b></div><p>'+escapeText(event.descricao)+'</p>'+(event.itens.length?'<div class="event-items">'+event.itens.map(item=>'<div><time>'+dateLabel(item.data)+'</time><span>'+escapeText(item.observacao)+'</span></div>').join('')+'</div>':'<p class="muted">Nenhuma observação adicionada.</p>')+'</article>').join('')||'<p class="muted">Nenhum evento especial registrado ainda.</p>'}
function openEventForm(){form.innerHTML='<h2>Novo evento especial</h2><p class="muted">Registre uma viagem, passeio ou acontecimento importante.</p><label for="eventType">Tipo</label><select id="eventType"><option>Viagem</option><option>Passeio</option><option>Acontecimento</option></select><label for="eventParticipant">Quem participou?</label><select id="eventParticipant"><option>Ambos</option><option>Eduardo</option><option>Jéssica</option></select><label for="eventStart">Data inicial</label><input id="eventStart" type="date" required><label class="event-single"><input id="eventSingle" type="checkbox" checked onchange="toggleEventEnd()"> Evento de um único dia</label><div id="eventEndWrap" hidden><label for="eventEnd">Data final</label><input id="eventEnd" type="date"></div><label for="eventDescription">Descrição</label><textarea id="eventDescription" maxlength="1000" placeholder="O que tornou esse momento especial?"></textarea><div class="event-items-head"><b>Observações do evento</b><button type="button" class="sub" onclick="addEventItem()">+ Adicionar item</button></div><div id="eventItemRows"></div><button class="primary" onclick="saveEvent()">Salvar evento</button>';el('eventStart').value=todayKey;el('eventEnd').value=todayKey;toggleEventEnd();if(!modal.open)modal.showModal()}
function toggleEventEnd(){const single=el('eventSingle').checked;el('eventEndWrap').hidden=single;if(single)el('eventEnd').value=el('eventStart').value}
function addEventItem(){const rows=el('eventItemRows'),row=document.createElement('div');row.className='event-item-row';row.innerHTML='<input type="date" aria-label="Data da observação" value="'+(el('eventStart').value||todayKey)+'"><textarea maxlength="500" placeholder="O que aconteceu?"></textarea><button type="button" class="edit-day" aria-label="Remover observação" onclick="this.parentElement.remove()">×</button>';rows.append(row)}
async function saveEvent(){const start=el('eventStart').value,end=el('eventSingle').checked?el('eventStart').value:el('eventEnd').value,items=[...document.querySelectorAll('.event-item-row')].map(row=>({data:row.querySelector('input').value,observacao:row.querySelector('textarea').value.trim()}));if(!start||!end||end<start||items.some(item=>!item.data||item.data<start||item.data>end||!item.observacao)){alert('Confira o período e as observações do evento. Cada item precisa estar dentro das datas escolhidas.');return}const event={tipo:el('eventType').value,participante:el('eventParticipant').value,dataInicio:start,dataFim:end,descricao:el('eventDescription').value.trim(),itens};try{const response=await fetch('/api/eventos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(event)});if(!response.ok)throw new Error();events=await (await fetch('/api/eventos',{cache:'no-store'})).json();renderEvents();modal.close();showHistory('events')}catch{alert('Não foi possível salvar o evento no Supabase.')}}
function renderHighlights(featuredDay){const record=days[featuredDay],panel=el('highlights');panel.hidden=!record;if(!record){panel.innerHTML='';return}const votes=Object.values(days).flatMap(item=>item.votes.filter(Boolean)),totalVotes=votes.length,overall=totalVotes?votes.reduce((sum,v)=>sum+v.score,0)/totalVotes:0,heartScale=Array.from({length:5},(_,i)=>{const fill=Math.max(0,Math.min(1,overall-i))*100;return '<div><span>'+(i+1)+'</span><b class="scale-heart" style="--heart-fill:'+fill+'%">♥</b></div>'}).join(''),overallPanel='<section class="overall-score" aria-label="Média geral do casal"><div><small>MÉDIA GERAL</small><strong>'+overall.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+' <span>/ 5</span></strong><p>'+totalVotes+' '+(totalVotes===1?'voto registrado':'votos registrados')+'</p></div><div class="heart-scale" role="img" aria-label="Média de '+overall.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+' de 5">'+heartScale+'</div></section>',marks=record.tags.map(i=>'<span>'+tags[i]+(i===0?' · '+escapeText(record.who):'')+'</span>').join(''),voices=people.map((name,i)=>{const vote=record.votes[i],score=vote?'<span class="voted-stars" aria-label="'+vote.score+' de 5 estrelas">'+ '★'.repeat(vote.score)+'<i>'+ '☆'.repeat(5-vote.score)+'</i></span>':'<em>Voto pendente</em>',note=vote?.note?'<blockquote>'+escapeText(vote.note)+'</blockquote>':'';return '<article><img src="'+photos[i]+'" alt=""><div><b>'+name+'</b>'+score+note+'</div></article>'}).join(''),average=done(featuredDay)?'<p class="average">Média do casal <b>'+((record.votes[0].score+record.votes[1].score)/2).toLocaleString('pt-BR')+' / 5</b></p>':'';panel.innerHTML=overallPanel+'<div class="highlight-record"><small>'+(featuredDay===todayKey?'HOJE · ':'ÚLTIMO REGISTRO · ')+dateLabel(featuredDay)+'</small><div class="marks">'+marks+'</div>'+(record.note?'<p class="shared-note">'+escapeText(record.note)+'</p>':'')+voices+average+'</div>'}
function openDay(d){day=d;el('date').textContent=fullDateLabel(d).toUpperCase();if(!modal.open)modal.showModal();if(days[d])overview();else edit()}
function edit(){draft=structuredClone(days[day]||empty());form.innerHTML='<h2>Como foi o nosso dia?</h2><p class="muted">Marquem juntos tudo que aconteceu.</p><div class="chips">'+tags.map((t,i)=>'<button aria-pressed="'+draft.tags.includes(i)+'" onclick="toggleTag('+i+',this)"><span aria-hidden="true">'+['😠','😊','🔥'][i]+'</span>'+t+'</button>').join('')+'</div><div id="conflict"><label for="who">Quem se envolveu na briga?</label><select id="who"><option>Os dois</option><option>Eduardo</option><option>Jéssica</option></select></div><label for="note">Observação do casal (opcional)</label><textarea id="note" maxlength="500"></textarea><button class="primary" id="saveDay" onclick="saveDay()">Salvar registro do casal</button>';el('note').value=draft.note;el('who').value=draft.who;updateTags()}
function toggleTag(i,b){draft.tags=draft.tags.includes(i)?draft.tags.filter(t=>t!==i):[...draft.tags,i];b.setAttribute('aria-pressed',draft.tags.includes(i));updateTags()}function updateTags(){el('conflict').hidden=!draft.tags.includes(0);el('saveDay').disabled=!draft.tags.length}function saveDay(){if(!draft.tags.length)return;draft.note=el('note').value.trim();draft.who=draft.tags.includes(0)?el('who').value:'Os dois';persist(structuredClone(draft))}
function overview(){let a=days[day],full=done(day);form.innerHTML='<h2>'+(full?'Resumo do dia':'A visão de cada um')+'</h2><p>'+a.tags.map(i=>tags[i]+(i===0?' ('+escapeText(a.who)+')':'')).join(' · ')+'</p>'+(a.note?'<p class="review">'+escapeText(a.note)+'</p>':'')+'<button class="sub" onclick="edit()">Editar registro do casal</button><div class="profiles">'+people.map((p,i)=>'<button onclick="vote('+i+')"><img src="'+photos[i]+'" alt="">'+p+'<small>'+(a.votes[i]?'Editar voto':'Votar')+'</small></button>').join('')+'</div>'+(full?'<h3>Média do casal · '+((a.votes[0].score+a.votes[1].score)/2).toLocaleString('pt-BR')+' / 5</h3>':'<p class="muted">Aguardando '+people.filter((_,i)=>!a.votes[i]).join(' e ')+'.</p>')+a.votes.map((v,i)=>v?'<div class="review"><img src="'+photos[i]+'" alt=""><b>'+people[i]+' · '+v.score+' ★</b><p>'+escapeText(v.note)+'</p></div>':'').join('')+'<button class="primary" onclick="modal.close()">Voltar à trilha</button>'}
function vote(i){person=i;let v=days[day].votes[i];rating=v?.score||0;form.innerHTML='<img class="portrait" src="'+photos[i]+'" alt=""><small>'+people[i].toUpperCase()+'</small><h2>Como foi o dia pra você?</h2><div class="stars">'+[1,2,3,4,5].map(n=>'<button aria-label="'+n+' estrelas" onclick="setScore('+n+')">★</button>').join('')+'</div><label for="reason">Quer contar o motivo? (opcional)</label><textarea id="reason" maxlength="500"></textarea><button class="primary" id="saveVote" onclick="saveVote()">Salvar meu voto</button><button class="sub" onclick="overview()">Voltar</button>';el('reason').value=v?.note||'';setScore(rating)}function setScore(n){rating=n;document.querySelectorAll('.stars button').forEach((b,i)=>{b.classList.toggle('on',i<n);b.setAttribute('aria-pressed',i+1===n)});el('saveVote').disabled=!n}function saveVote(){if(!rating)return;const record=structuredClone(days[day]);record.votes[person]={score:rating,note:el('reason').value.trim()};persist(record)}
function startApp(){el('accessGate').hidden=true;document.body.classList.remove('locked');initialize().catch(()=>{setDataStatus('Supabase fora do ar');el('entries').textContent='Não foi possível carregar os dados do Supabase.'})}
function unlock(event){event.preventDefault();const input=el('accessPassword'),error=el('accessError');if(input.value==='1104'){sessionStorage.setItem('modo-cumplice-authorized','1');startApp()}else{error.textContent='Senha incorreta.';input.value='';input.focus()}}
document.body.classList.add('locked');setupDrag();if(sessionStorage.getItem('modo-cumplice-authorized')==='1')startApp();else setTimeout(()=>el('accessPassword').focus(),0)
